lines = [
    '# # ## ## ## ## # ### ### ### ### ##  ### ### # ##   # ### ###### # #  ##  #    #  # ## #  ###  #  ## # #  #  ###  ## # #   ##  #   ##  ## ######  # ## #   # #### ######  ###  #   ## ##  # ## #  ## # #   ##  ## #  #### ######   #   #  # ## #  #   ##  ##   #  #  ###  ## # #   ##  #   ##  ## ######  ##  ##  #  ###   # # #   # ###   # ###  ## # #   ## ##   ##  ## #  #### ######   # ###  #    #  #    #   # ###  # ####  #  ###  ## # #   ##  #   ##  ## ######  ### ##  # ## #   # ###  ## # #   ##  ## #',
    '  #### ######  #  # #  #    #   # # #   # ###  # ####  #  ###  ## # #   ##  #   ##  ## ######  #  # #   # # #   # ###   # ###  ## # #   ## ##   ##  ## #   ### ####### #  # ## #  # ## ###### ###   #  #    #  #  ###  #  ###   # # #  #  # ## #  #### ###### # ## ##  # ## #  ## ###  ## ###  #  ###  ## # #   ##  ## ######  # ## #  #   ### ######   # ###  # ####  ## # ## ###### ### ###  #### #   ## ##  # #  #### # ## ####  # ## ## # # ##### ## #### ### # # # ## ###   # ### ###### ## #### # ### # ###   ',
    '# ###  ## # ##### ##   ##    #  #  ## # #  #  ###    # ##  #  ###    ## #  # ####  #    # #     #  ## # #  ## # #  ## ###  #  ###    ####   ## ##  ##   # #     #  ## # #   #  ## #     #  ###  #  #  ###   # ###  #  # #    ## #   #  ## #     #   #   #   #  ##   ### # #     #    ## #  #### #    # ##  ##  ##  # ####     # ########                                                                                                                                                                            '
]
maxlen = max(len(l) for l in lines)
lines = [l.ljust(maxlen, ' ') for l in lines]

b2 = ''.join(lines).replace(' ', '0').replace('#', '1')

# Invert bits
b2_inv = ''.join('0' if c == '1' else '1' for c in b2)
chars = []
for i in range(0, len(b2_inv) - 7, 8):
    chars.append(chr(int(b2_inv[i:i+8], 2)))

print(''.join(chars))
